fn is_greater(n: i32, a: &Vec<i32>) -> bool {
    // Iterate through each element in the vector
    for &elem in a.iter() {
        // If we find an element that is greater than or equal to n,
        // then n is not strictly greater than every element.
        if elem >= n {
            return false;
        }
    }
    // If no element was ≥ n, then n is strictly greater than all elements.
    true
}

